mapper.select:
SELECT * FROM TBL_BILL_MATURITY
WHERE DELETE_FLAG = 0

    AND BILL_NUMBER LIKE '%' || #{query.billNumber} || '%'


    AND BILL_TYPE = #{query.billType}


    AND MATURITY_STATUS = #{query.maturityStatus}


    AND MATURITY_DATE >= #{query.maturityDateStart}


    AND MATURITY_DATE <= #{query.maturityDateEnd}


    AND REMAINING_DAYS >= #{query.remainingDaysMin}


    AND REMAINING_DAYS <= #{query.remainingDaysMax}


    AND BILL_AMOUNT >= #{query.amountMin}


    AND BILL_AMOUNT <= #{query.amountMax}


    AND COMPANY_ID = #{query.companyId}

ORDER BY MATURITY_DATE ASC

