mapper.select:
SELECT MATURITY_DATE as "maturityDate", COUNT(*) as "count", SUM(BILL_AMOUNT) as "totalAmount"
FROM TBL_BILL_MATURITY
WHERE DELETE_FLAG = 0 AND MATURITY_DATE BETWEEN #{startDate} AND #{endDate}

    AND COMPANY_ID = #{companyId}

GROUP BY MATURITY_DATE ORDER BY MATURITY_DATE
